<?php require_once __DIR__.'/../_bootstrap.php';$u=user();$d=body();required($d,['name','unique_identifier','identifier_type','cost_price','selling_price']);if(!in_array($d['identifier_type'],['imei','serial']))fail('Invalid identifier type');
try{$s=db()->prepare('INSERT INTO products(user_id,name,brand,category,unique_identifier,identifier_type,cost_price,selling_price,condition_status,description) VALUES(?,?,?,?,?,?,?,?,?,?)');$s->execute([$u['id'],trim($d['name']),$d['brand']??null,$d['category']??'phone',trim($d['unique_identifier']),$d['identifier_type'],(float)$d['cost_price'],(float)$d['selling_price'],$d['condition_status']??'used',$d['description']??null]);$id=(int)db()->lastInsertId();out(['success'=>true,'product'=>product_row(['id'=>$id]+$d)],201);}catch(PDOException $e){fail($e->getCode()==='23000'?'IMEI/Serial already exists':'Could not save product');}
